.dm-afx-tray .dm-ib:focus-visible{outline-offset:-2px}
.dm-afx-tsep{flex:none;width:1px;height:16px;margin-right:3px;background:var(--dm-line)}
@media (hover:none){.dm-afx-chip:not(.dm-is-writing) .dm-afx-tray{grid-template-columns:1fr;opacity:1}}
@container (max-width:400px){.dm-afx-in-m :is(.dm-afx-when,.dm-afx-msep){display:none}}
/* stack: the report as a stack of paper. The newest page is written onto it; Versions lays the sheets out to pick one */
.dm-afx-st{display:flex;flex-direction:column;align-items:center;gap:18px;--dm-sw:150px;--dm-sh:194px;--dm-fx:min(122px,calc((100cqw - var(--dm-sw) - 24px) / 2));--dm-ln:color-mix(in srgb,var(--dm-fg) 26%,var(--dm-surface))}
@container (max-width:360px){.dm-afx-st{--dm-sw:112px;--dm-sh:146px}}
.dm-afx-desk{position:relative;width:var(--dm-sw);height:calc(var(--dm-sh) + 24px)}
/* in Soft the stack casts a soft shadow on the desk, which fades as the sheets are laid out */
.dm-afx-desk::before{content:"";position:absolute;left:4%;right:4%;bottom:-10px;height:26px;border-radius:50%;background:radial-gradient(closest-side,rgba(0,0,0,.13),transparent);transition:opacity var(--dm-t) var(--dm-ease)}
:root[data-theme="dark"] .dm-afx-desk::before{background:radial-gradient(closest-side,rgba(0,0,0,.5),transparent)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-afx-desk::before{background:radial-gradient(closest-side,rgba(0,0,0,.5),transparent)}}
:root:not([data-style="soft"]) .dm-afx-desk:not(:where([data-style="soft"],[data-style="soft"] *))::before,.dm-afx-st.dm-fan .dm-afx-desk::before{opacity:0}
.dm-afx-stack{position:absolute;inset:0}
/* the top sheet stands straight, the older ones sit just behind it; pointing at the stack or focusing it, they peek out
   up and to the left, a few pixels each */
.dm-afx-sh{--dm-pk:-1.5px;position:absolute;left:0;top:12px;width:var(--dm-sw);height:var(--dm-sh);padding:0;text-align:left;border-radius:10px;background:var(--dm-surface);box-shadow:var(--dm-shadow);transform:translate(calc(var(--dm-d,0) * var(--dm-pk)),calc(var(--dm-d,0) * var(--dm-pk)));transition:transform var(--dm-t-slow) var(--dm-ease),box-shadow var(--dm-t) var(--dm-ease)}
.dm-afx-st:not(.dm-fan):not(.dm-is-writing):has(:focus-visible) .dm-afx-sh{--dm-pk:-4px}
@media (hover:hover) and (pointer:fine){.dm-afx-st:not(.dm-fan):not(.dm-is-writing) .dm-afx-desk:hover .dm-afx-sh{--dm-pk:-4px}}
.dm-afx-sh:focus-visible{outline-offset:3px}
.dm-afx-st:not(.dm-fan) .dm-afx-sh[aria-checked="true"]{box-shadow:var(--dm-shadow-pop)}
.dm-afx-st.dm-is-writing .dm-afx-sh{cursor:default}
.dm-afx-pg{position:absolute;inset:0;display:flex;flex-direction:column;padding:12px;border-radius:inherit;overflow:hidden}
.dm-afx-st-k{display:flex;align-items:center;justify-content:space-between;font-size:11px;line-height:14px;color:var(--dm-afx-t2)}
.dm-afx-st-h{min-height:32px;margin-top:4px;font-size:12.5px;font-weight:500;line-height:16px;color:var(--dm-fg)}
.dm-afx-st-ls{display:flex;flex-direction:column;gap:7px;margin-top:10px}
.dm-afx-r{position:relative;display:flex;align-items:center;gap:5px;height:4px}
.dm-afx-r i{display:block;height:3px;border-radius:2px;width:var(--dm-w);background:var(--dm-ln);transform-origin:left center}
.dm-afx-r b{flex:none;width:4px;height:4px;border-radius:50%;background:var(--dm-ln)}
.dm-afx-r.dm-n b{width:6px;height:6px;margin:0 -1px;background:var(--dm-accent-mark)}
.dm-afx-gap{height:3px}
.dm-afx-st .dm-blank .dm-afx-r :is(i,b){transform:scaleX(0)}
.dm-afx-pen{position:absolute;left:0;top:0;width:7px;height:7px;border-radius:50%;background:var(--dm-accent-mark);box-shadow:0 0 0 3px color-mix(in srgb,var(--dm-accent-mark) 25%,transparent);opacity:0;pointer-events:none}
@container (max-width:360px){.dm-afx-st-ls{gap:6px;margin-top:8px}.dm-afx-st-ls>:nth-child(n+7){display:none}}
.dm-afx-tab{position:absolute;left:50%;top:calc(100% + 10px);display:inline-flex;align-items:center;gap:4px;transform:translateX(-50%);white-space:nowrap;font-size:11.5px;color:var(--dm-afx-t2);opacity:0;transition:opacity var(--dm-t) var(--dm-ease)}
.dm-afx-tab .dm-i{display:none;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-afx-st.dm-fan .dm-afx-tab{opacity:1}
.dm-afx-sh[aria-checked="true"] .dm-afx-tab{color:var(--dm-fg);font-weight:500}
.dm-afx-sh[aria-checked="true"] .dm-afx-tab .dm-i{display:inline-block}
@container (max-width:360px){.dm-afx-tab .dm-afx-ta{display:none}}
.dm-afx-cap{display:flex;flex-direction:column;align-items:center;max-width:100%;text-align:center;transition:margin var(--dm-t) var(--dm-ease)}
.dm-afx-st.dm-fan .dm-afx-cap{margin-top:22px}
.dm-afx-st-t{font-size:14px;font-weight:500}
.dm-afx-st-m{justify-content:center;max-width:100%}
.dm-afx-note{padding-top:2px;font-size:12.5px;color:var(--dm-fg)}
.dm-afx-st-act{display:flex;align-items:center;gap:4px;transition:opacity var(--dm-t) var(--dm-ease)}
.dm-afx-st-act .dm-pill{gap:6px}
.dm-afx-st.dm-is-writing .dm-afx-st-act{opacity:0;visibility:hidden}

